scripts.蔷薇对话.txt:
	If ($Event == 550) @Label1;
	Goto @end;

@Label1:
	If ($QiangWeiSense >= 20) @AddSenseEnd;
		Add($SenseVal, 5);
		Add($QiangWeiSense, 5);
	@AddSenseEnd:
	If ($qiangweiTalk == 0) @Talk1;
	If ($qiangweiTalk == 1) @Talk2;
	If ($qiangweiTalk == 2) @Talk3;
	If ($qiangweiTalk == 3) @Talk4;
	If ($qiangweiTalk == 4) @Talk5;
	Goto @end;
	
@Talk1:
	Talk(10490, 10490);
	Assign($qiangweiTalk, 1);
	Goto @end;
	
@Talk2:
	Say("杨影枫：蔷薇姑娘，你这样到处乱跑，你家里的人都很着急。", 2);
	Say("蔷薇：家里没有人陪我玩，所以我就自己出来玩啦。", 31);
	Assign($qiangweiTalk, 2);
	Goto @end;
	
@Talk3:	
	Say("蔷薇：你是我爹的客人吗？我以前好像没有见过你。", 29);
	Say("杨影枫：我是第一次来拜访你爹，想和他切磋一下武艺。", 2);
	Say("蔷薇：哦，好多人和你一样来找我爹，不过都被我爹打败了。", 29);
	Say("杨影枫：……", 2);
	Assign($qiangweiTalk, 3);
	Goto @end;
	
@Talk4:
	Say("蔷薇：你别怕，呆会我和爹说，让他下手轻点……", 29);
	Say("杨影枫：在下即便功力不济，也不敢有劳姑娘。", 2);
	Say("蔷薇：哼，好心没好报，不理你了……", 29);
	Assign($qiangweiTalk, 4);
	Return;
	
@Talk5:
	Say("杨影枫：蔷薇姑娘，我们快走吧。", 2);
	Say("蔷薇：（没听见状）……", 29);
	Say("杨影枫：蔷薇姑娘……", 2);
	Say("蔷薇：我不是在走吗？……", 29);
	Say("杨影枫：（苦笑，自言自语）好刁蛮的姑娘。", 2);
	Say("蔷薇：你说什么？！", 29);
	Say("杨影枫：没，没什么……", 2);
	Return;
@end:
	Return;

